  function renderPager(entity,d){const p=$(`.pager[data-entity="${entity}"]`);if(!p)return;const pages=Math.ceil(d.total/d.size);p.innerHTML=pages>1?`<button ${d.page<=1?'disabled':''} data-page="${d.page-1}">‹</button><span class="p-2">${d.page} / ${pages}</span><button ${d.page>=pages?'disabled':''} data-page="${d.page+1}">›</button>`:'';$$('button',p).forEach(b=>b.onclick=()=>loadList(entity,b.dataset.page))}
  function fieldHtml(def,value){const[n,label,type,required]=def,id=`fld_${n}`,req=required?'required':'';let input;if(type==='textarea')input=`<textarea class="form-control" name="${n}" rows="2" ${req}>${esc(value)}</textarea>`;else if(type==='checkbox')input=`<div class="form-check form-switch mt-2"><input type="checkbox" class="form-check-input" name="${n}" value="1" ${value===undefined||value==1?'checked':''}></div>`;else if(type.startsWith('select:'))input=`<select class="form-select" name="${n}" ${req}>${type.slice(7).split('|').map(x=>`<option value="${x}" ${value===x?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select>`;else if(['contract','job','union','period'].includes(type)){const map={contract:['sozlesmeler','ad'],job:['isler','ad'],union:['sendikalar','ad'],period:['donemler','ad']},[key,text]=map[type];input=`<select class="form-select" name="${n}" ${req}><option value="">Seçiniz</option>${state.options[key].map(x=>`<option value="${x.id}" ${String(value)===String(x.id)?'selected':''}>${esc(x[text])}</option>`).join('')}</select>`}else input=`<input id="${id}" class="form-control" name="${n}" type="${type}" value="${esc(value??'')}" ${type==='number'?'step="0.01"':''} ${req}>`;return`<div class="${type==='textarea'?'col-12':'col-md-6'}"><label class="${required?'required':''}">${label}</label>${input}</div>`}
  function openForm(entity,row={}){$('#recordModal').classList.remove('progress-detail-mode');const isRightVersion=entity==='sendikal_haklar'&&row.id;const values=isRightVersion?{...row,gecerlilik_baslangic:'',gecerlilik_bitis:''}:row;$('#recordModal .modal-footer .btn-primary').hidden=false;$('#recordForm').dataset.entity=entity;$('#recordForm [name=id]').value=row.id||'';$('#recordModal .modal-title').textContent=isRightVersion?'Sendikal hakkın yeni sürümü':(row.id?'Kaydı düzenle: ':'Yeni ')+$(`#moduleNav [data-section="${entity}"]`).innerText.trim();$('#formFields').innerHTML=(isRightVersion?'<div class="col-12"><div class="alert alert-info mb-0">Eski kayıt değiştirilmeyecek. Yeni değerler gireceğiniz başlangıç tarihinden itibaren geçerli olacak; eski sürüm bir gün öncesinde otomatik kapanacak.</div></div>':'')+schemas[entity].map(d=>fieldHtml(d,values[d[0]])).join('');modal.show()}
  function openRightsPreset(){if(!state.options.donemler.length){notify('Önce bir TİS dönemi oluşturun.','warning');return}$('#recordModal .modal-footer .btn-primary').hidden=false;$('#recordForm').dataset.entity='_seed_rights';$('#recordForm [name=id]').value='';$('#recordModal .modal-title').textContent='Listedeki sendikal hakları getir';$('#formFields').innerHTML='<div class="col-12"><div class="alert alert-info mb-0">Gönderdiğiniz listedeki 31 farklı hak, bordrodaki kalem adıyla eşleştirilerek eklenir. Tutarlar personel bordrosundan alınır. Var olan aynı adlı haklar tekrar eklenmez.</div></div>'+fieldHtml(['tis_donem_id','TİS dönemi','period',1],'')+fieldHtml(['gecerlilik_baslangic','Şu tarihten itibaren geçerli','date',1],'');modal.show()}
  async function saveForm(e){e.preventDefault();const entity=e.currentTarget.dataset.entity,data=Object.fromEntries(new FormData(e.currentTarget));schemas[entity].filter(d=>d[2]==='checkbox').forEach(d=>data[d[0]]=e.currentTarget.elements[d[0]].checked?1:0);try{await api(entity==='personeller'?'save_personnel':'save',{method:'POST',body:entity==='personeller'?{data}:{entity,data}});modal.hide();notify(entity==='sendikal_haklar'&&data.id?'Eski hak korundu; yeni tarihli sürüm oluşturuldu.':'Kayıt başarıyla kaydedildi.');await loadOptions();loadList(entity);dashboard()}catch(e){notify(e.message,'danger')}}
