  function timesheetCell(v){const n=Number(v||0);return Math.abs(n)<.005?'':reportNumber(n)}
  function timesheetDate(v){const p=String(v||'').split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:''}
  function payrollTimesheetHtml(d){const p=d.payroll||{},rows=d.rows||[],cols=d.columns||[],days=Number(d.days||30),dayHeaders=Array.from({length:days},(_,i)=>`<th>${i+1}</th>`).join(''),weekdays=Array.from({length:days},(_,i)=>{const dt=new Date(Number(p.yil),Number(p.ay)-1,i+1);return`<th>${['Pz','Pt','Sa','Ça','Pe','Cu','Ct'][dt.getDay()]}</th>`}).join(''),detailHeaders=cols.map(c=>`<th>${esc(c.label)}</th>`).join(''),detailUnits=cols.map(c=>`<th>${esc(c.unit)}</th>`).join(''),detailCells=r=>cols.map(c=>`<td>${timesheetCell(r.detaylar?.[c.key])}</td>`).join(''),totals=key=>rows.reduce((s,r)=>s+Number(r[key]||0),0),detailTotals=cols.map(c=>`<th>${timesheetCell(rows.reduce((s,r)=>s+Number(r.detaylar?.[c.key]||0),0))}</th>`).join('');return`<div class="col-12"><div class="d-flex justify-content-between align-items-center gap-3 mb-3"><div class="progress-source mb-0"><strong>Kaynak bordro:</strong> #${esc(p.id)} · ${esc(p.dosya_adi)} · Sürüm ${esc(p.surum)}<br><strong>İşyeri / Dönem:</strong> ${esc(p.is_adi)} · ${esc(p.yil)}/${String(p.ay).padStart(2,'0')}</div><a class="btn btn-success flex-shrink-0" href="${cfg.api}?action=export_payroll_timesheet&id=${encodeURIComponent(p.id||'')}">Formüllü Excel İndir</a></div><div class="table-responsive timesheet-template-wrap"><table class="timesheet-template-sheet"><thead><tr><th rowspan="2">Sıra No</th><th rowspan="2">Ad Soyad</th><th rowspan="2">T.C. Kimlik No</th><th rowspan="2">Giriş Tarihi</th><th rowspan="2">Çıkış Tarihi</th>${dayHeaders}<th>Çalışılan</th><th>SSK</th><th>İzin</th><th>Toplam</th><th>Eksik</th><th rowspan="2">Eksik Gün Neden</th>${detailHeaders}<th rowspan="2">İMZA</th></tr><tr>${weekdays}<th>Gün</th><th>Gün</th><th>Gün</th><th>Gün</th><th>Gün</th>${detailUnits}</tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.ad_soyad)}</td><td>${esc(r.tc_kimlik_no)}</td><td>${timesheetDate(r.ise_giris_tarihi)}</td><td>${timesheetDate(r.isten_cikis_tarihi)}</td>${Array.from({length:days},(_,x)=>`<td class="day-code">${esc(r.gunler?.[x+1]||'')}</td>`).join('')}<td>${timesheetCell(r.calisilan_gun)}</td><td>${timesheetCell(r.ssk_gun)}</td><td>${timesheetCell(r.izin_gun)}</td><td>${timesheetCell(r.toplam_gun)}</td><td>${timesheetCell(r.eksik_gun)}</td><td>${esc(String(r.eksik_neden||'').trim())}</td>${detailCells(r)}<td></td></tr>`).join('')}</tbody><tfoot><tr><th colspan="${5+days}">GENEL TOPLAM</th><th>${timesheetCell(totals('calisilan_gun'))}</th><th>${timesheetCell(totals('ssk_gun'))}</th><th>${timesheetCell(totals('izin_gun'))}</th><th>${timesheetCell(totals('toplam_gun'))}</th><th>${timesheetCell(totals('eksik_gun'))}</th><th></th>${detailTotals}<th></th></tr></tfoot></table></div><div class="timesheet-legend"><strong>Kod Açıklamaları</strong><span>N: Normal</span><span>O: Gündüz Mesaisi</span><span>G: Gece Mesaisi</span><span>Y: Yarım Gün</span><span>H: Hafta Tatili</span><span>T: Resmi Tatil</span><span>İ: İzinli</span><span>S: Yıllık İzin</span><span>R: Raporlu</span><span>E: Eksik Gün</span></div></div>`}
  async function openTimesheet(r){try{const d=await api('payroll_timesheet',{query:{id:r.bordro_id||r.id}}),p=d.payroll||{};$('#recordModal').classList.add('progress-detail-mode');$('#recordModal .modal-footer .btn-primary').hidden=true;$('#recordForm').dataset.entity='_view';$('#recordForm [name=id]').value=p.id||'';$('#recordModal .modal-title').textContent=`Bordro Bazlı Puantaj: ${p.yil}/${String(p.ay).padStart(2,'0')}`;$('#formFields').innerHTML=payrollTimesheetHtml(d);modal.show()}catch(e){notify(e.message,'danger')}}
  function payrollMovementHtml(d){const p=d.payroll||{},rows=d.rows||[],rights=d.rights||[],t=d.totals||{},c=d.cost_summary||{},rightHeaders=rights.map(x=>`<th>${esc(x.label)}</th>`).join(''),rightCells=r=>rights.map(x=>`<td>${reportNumber(r.haklar?.[x.key])}</td>`).join(''),rightTotals=rights.map(x=>`<th>${reportNumber(t.haklar?.[x.key])}</th>`).join(''),costTable=`<div class="payroll-cost-block"><h6>HAKEDİŞ MALİYET TABLOSU</h6>${c.bordro_ozeti_var?'':`<div class="alert alert-warning py-2">İşveren primleri eski yüklemede kaydedilmemiş. Kesin hesap için bordroyu yeniden yükleyin.</div>`}<div class="table-responsive"><table class="payroll-cost-sheet"><thead><tr><th>TOPLAM KAZANÇ</th><th>SSK PRİM İŞVEREN</th><th>İŞSİZLİK PRİM İŞVEREN</th><th>PRİMLER DAHİL TOPLAM</th><th>KÂR PAYI (%${reportNumber(c.kar_orani).replace(',00','')})</th><th>GENEL GİDER (%${reportNumber(c.genel_gider_orani).replace(',00','')})</th><th>TOPLAM HAKEDİŞ TUTARI</th></tr></thead><tbody><tr><td>${reportNumber(c.toplam_kazanc)}</td><td>${reportNumber(c.ssk_prim_isveren)}</td><td>${reportNumber(c.issizlik_prim_isveren)}</td><td>${reportNumber(c.baz_toplam)}</td><td>${reportNumber(c.kar_tutari)}</td><td>${reportNumber(c.genel_gider_tutari)}</td><td>${reportNumber(c.toplam_hakedis_tutari)}</td></tr></tbody></table></div></div>`;return`<div class="col-12"><div class="progress-source"><strong>Kaynak bordro:</strong> #${esc(p.id)} · ${esc(p.dosya_adi)} · Sürüm ${esc(p.surum)}<br><strong>Sözleşme / İş:</strong> ${esc(p.sozlesme_adi)} / ${esc(p.is_adi)}</div>${rows.length?`<div class="movement-summary"><span>Bordro Toplam Kazanç: <strong>${reportNumber(t.toplam_kazanc)}</strong></span><span>Toplam Hakediş: <strong>${reportNumber(t.hakedis_toplami)}</strong></span><span class="${Math.abs(Number(t.fark))<.01?'match':'mismatch'}">Fark: <strong>${reportNumber(t.fark)}</strong></span></div><div class="table-responsive progress-detail-wrap"><table class="progress-detail-sheet payroll-movement-sheet"><thead><tr><th rowspan="2">SIRA</th><th rowspan="2">AD SOYAD</th><th colspan="3" class="movement-group payroll-group">BORDRO HAREKETLERİ</th><th colspan="${rights.length+3}" class="movement-group progress-group">HAKEDİŞ HAREKETLERİ</th></tr><tr><th>NORMAL KAZANÇ</th><th>DİĞER KAZANÇ</th><th>TOPLAM KAZANÇ</th><th>NORMAL KAZANÇ</th>${rightHeaders}<th>TOPLAM HAKEDİŞ TUTARI</th><th>FARK</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${Math.abs(Number(r.fark))<.01?'movement-match':'movement-diff'}"><td>${i+1}</td><td>${esc(r.ad_soyad)}</td><td>${reportNumber(r.normal_kazanc)}</td><td>${reportNumber(r.diger_kazanc)}</td><td>${reportNumber(r.toplam_kazanc)}</td><td>${reportNumber(r.hakedis_normal_kazanc)}</td>${rightCells(r)}<td>${reportNumber(r.hakedis_toplami)}</td><td>${reportNumber(r.fark)}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="2">GENEL TOPLAM</th><th>${reportNumber(t.normal_kazanc)}</th><th>${reportNumber(t.diger_kazanc)}</th><th>${reportNumber(t.toplam_kazanc)}</th><th>${reportNumber(t.hakedis_normal_kazanc)}</th>${rightTotals}<th>${reportNumber(t.hakedis_toplami)}</th><th>${reportNumber(t.fark)}</th></tr></tfoot></table></div>${costTable}`:'<div class="alert alert-warning mb-0">Bordrodan kazanç hareketi bulunamadı. Bordroyu yeniden yükleyin.</div>'}${Number(p.aktif)!==1?'<div class="alert alert-secondary mt-3 mb-0">Bu eski bir bordro sürümüdür. Hareketler görüntülenebilir; hakediş yalnızca aktif sürümden oluşturulur.</div>':''}</div>`}
  async function openPayrollMovements(id){try{const d=await api('payroll_movements',{query:{id}}),p=d.payroll||{},rows=d.rows||[],primary=$('#recordModal .modal-footer .btn-primary');$('#recordModal').classList.add('progress-detail-mode');$('#recordForm').dataset.entity='_payroll_movements';$('#recordForm [name=id]').value=id;$('#recordModal .modal-title').textContent=`Bordro Hakediş Hareketleri: ${p.yil}/${String(p.ay).padStart(2,'0')}`;primary.hidden=Number(p.aktif)!==1||!rows.length||!d.cost_summary?.bordro_ozeti_var;primary.textContent='Hakedişi Oluştur';$('#formFields').innerHTML=payrollMovementHtml(d);modal.show()}catch(e){notify(e.message,'danger')}}
  async function openProgress(id){try{const d=await api('progress_detail',{query:{id}}),s=d.summary||{},rows=d.rows||[],payrolls=[...new Map(rows.filter(x=>x.bordro_id).map(x=>[x.bordro_id,x])).values()],dateParts=String(s.rapor_tarihi||'').split('-'),detailYear=dateParts[0]||new Date().getFullYear(),detailMonth=['','OCAK','ŞUBAT','MART','NİSAN','MAYIS','HAZİRAN','TEMMUZ','AĞUSTOS','EYLÜL','EKİM','KASIM','ARALIK'][Number(dateParts[1])]||'';$('#recordModal').classList.add('progress-detail-mode');$('#recordForm').dataset.entity='_view';$('#recordModal .modal-title').textContent='Bordroya Bağlı Hakediş Detayı';$('#recordModal .modal-footer .btn-primary').hidden=true;const payrollText=payrolls.length?payrolls.map(x=>`#${esc(x.bordro_id)} · ${esc(x.bordro_dosyasi)} · Sürüm ${esc(x.bordro_surum)}`).join(' | '):'Bordro bağlantısı bulunamadı';$('#formFields').innerHTML=`<div class="col-12"><div class="progress-source"><strong>Kaynak bordro:</strong> ${payrollText}</div><div class="table-responsive progress-detail-wrap"><table class="progress-detail-sheet"><thead><tr><th colspan="11">YAPILAN İŞLER LİSTESİ ${detailYear} (TEKLİF BİRİM FİYATLI HİZMET İÇİN)</th></tr><tr><th colspan="9">PERSONEL HİZMET ALIMI İŞİ ${detailMonth} ${detailYear}</th><th colspan="2">HAKEDİŞ NO: ${esc(s.hak_edis_no||'')}</th></tr><tr><th>SIRA NO</th><th>AD SOYAD</th><th>AÇIKLAMA</th><th>BİRİMİ</th><th>TEKLİF BİRİM FİYATI</th><th>TOPLAM İMALAT MİKTARI</th><th>ÖNCEKİ HAKEDİŞLER İMALAT MİKTARI</th><th>BU HAKEDİŞ MİKTARI</th><th>TOPLAM İMALAT TUTARI</th><th>ÖNCEKİ HAKEDİŞLER TUTARI</th><th>BU HAKEDİŞ TUTARI</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.ad_soyad)}</td><td>${esc(x.hak_kalemi)}</td><td>${esc(String(x.birim||'').toUpperCase())}</td><td>${reportNumber(x.birim_fiyat)}</td><td>${reportNumber(x.toplam_miktar)}</td><td>${reportNumber(x.onceki_miktar)}</td><td>${reportNumber(x.bu_hakedis_miktari)}</td><td>${reportNumber(x.kumulatif_toplam)}</td><td>${reportNumber(x.onceki_ay_toplami)}</td><td>${reportNumber(x.bu_ayki_kazanc)}</td></tr>`).join('')}</tbody></table></div></div>`;modal.show()}catch(e){notify(e.message,'danger')}}
  async function openProgressEdit(id){try{$('#recordModal').classList.remove('progress-detail-mode');const d=await api('progress_edit_data',{query:{id}});$('#recordForm').dataset.entity='_progress_edit';$('#recordForm [name=id]').value=id;$('#recordModal .modal-title').textContent=`Hakediş düzelt: ${d.yil}/${String(d.ay).padStart(2,'0')}`;$('#recordModal .modal-footer .btn-primary').hidden=false;const fields=[['hak_edis_no','Hakediş No','text'],['rapor_tarihi','Rapor tarihi','date'],['sozlesme_fiyatlariyla_hizmet','Hizmet tutarı','number'],['fiyat_farki','Fiyat farkı','number'],['onceki_hakedis_toplami','Önceki hakediş toplamı','number'],['kdv_orani','KDV oranı (%)','number'],['damga_vergisi','Ödemeye ait damga vergisi','number'],['durum','Durum','select:taslak|onayli|iptal']];$('#formFields').innerHTML='<div class="col-12"><div class="alert alert-light mb-0">Tutar değişikliklerinden sonra KDV, tahakkuk, kesinti toplamı ve ödenecek tutar otomatik hesaplanır.</div></div>'+fields.map(f=>fieldHtml(f,d[f[0]])).join('');modal.show()}catch(e){notify(e.message,'danger')}}
