  function showUnmatched(rows){if(!rows.length)return;$('#recordForm').dataset.entity='_view';$('#recordModal .modal-title').textContent=`Eşleşmeyen personeller (${rows.length})`;$('#recordModal .modal-footer .btn-primary').hidden=true;$('#formFields').innerHTML=`<div class="col-12"><p class="alert alert-warning">Bu personeller bordroya kaydedildi ancak puantaj oluşturulmadı. Personel kartlarını T.C. kimlik numarasıyla tanımlayıp bordroyu “Aktif sürümü güncelle” seçeneğiyle yeniden yükleyin.</p><div class="table-responsive"><table class="table"><thead><tr><th>Excel satırı</th><th>Ad soyad</th><th>T.C.</th><th>SGK</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.satir)}</td><td>${esc(x.ad_soyad)}</td><td>${esc(x.tc)}</td><td>${esc(x.sgk)}</td></tr>`).join('')}</tbody></table></div></div>`;modal.show()}
  async function upload(form,action){const data=new FormData(form);data.append('action',action);if(action==='upload_payroll'){['auto_personnel','auto_rights','auto_split_jobs','replace_period','create_progress'].forEach(name=>{if(form.elements[name])data.set(name,form.elements[name].checked?'1':'0')})}try{const r=await api(action,{method:'POST',body:data});if(action==='upload_payroll'){const rights=r.otomatik_haklar||{};if(r.format==='zirve_toplu_is_bazli_bordro'){const errors=r.hakedis_hatalari||[];notify(`${r.toplam_personel} personel ${r.is_sayisi} işe ayrıldı; ${r.olusturulan_personel||0} yeni personel, ${r.bordrolar?.length||0} bordro ve ${r.hakedisler?.length||0} hakediş oluşturuldu.${errors.length?' '+errors.length+' hakediş oluşturulamadı.':''}`,errors.length?'warning':'success');if(errors.length)showPayrollProgressErrors(errors)}else{notify(`${r.toplam_personel||r.eslesen+r.eslesmeyen.length} personel okundu; ${r.olusturulan_personel||0} yeni personel, ${rights.hak_kalemi||0} hak kalemi ve ${rights.personel_hakki||0} personel hakkı otomatik işlendi.`);showUnmatched(r.eslesmeyen)}}else notify(`${r.personel} personelde ${r.fark} fark bulundu.`);form.reset();if(action==='upload_payroll'){['auto_personnel','auto_rights','auto_split_jobs','replace_period','create_progress'].forEach(name=>{if(form.elements[name])form.elements[name].checked=true})}loadList(action==='upload_payroll'?'bordrolar':'karsilastirmalar');dashboard()}catch(e){notify(e.message,'danger')}}
  function showPayrollProgressErrors(rows){$('#recordForm').dataset.entity='_view';$('#recordModal .modal-title').textContent='Hakediş Oluşturma Kontrolü';$('#recordModal .modal-footer .btn-primary').hidden=true;$('#formFields').innerHTML=`<div class="col-12"><div class="alert alert-warning">Bordrolar kaydedildi; aşağıdaki işlerde hakediş oluşturulamadı.</div><div class="table-responsive"><table class="table"><thead><tr><th>Bordro</th><th>Açıklama</th></tr></thead><tbody>${rows.map(x=>`<tr><td>#${esc(x.bordro_id)}</td><td>${esc(x.message)}</td></tr>`).join('')}</tbody></table></div></div>`;modal.show()}
