  function selectedReportMonth(){return Number($('.report-month.active')?.dataset.month||new Date().getMonth()+1)}
  function reportFilters(){return{yil:$('#reportYear').value,ay:selectedReportMonth(),is_id:$('#reportJob')?.value||''}}
  function reportDate(v){const p=String(v||'').split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:esc(v)}
  function reportNumber(v){return new Intl.NumberFormat('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))}
  function compactReportNumber(v){return new Intl.NumberFormat('tr-TR',{notation:'compact',maximumFractionDigits:1}).format(Number(v||0))+' ₺'}
  function jobReportHtml(d){const months=['','Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'],s=d.summary||{},jobs=d.jobs||[],flow=d.months||[],selected=months[Number(d.ay)]||'';const table=jobs.length?`<div class="table-responsive job-report-table-wrap"><table class="job-report-table"><thead><tr><th rowspan="2">İş / Sözleşme</th><th colspan="2">Hizmet Tutarı</th><th colspan="2">Genel Gider</th><th colspan="2">Yüklenici Kârı</th><th colspan="2">Genel Toplam (KDV Hariç)</th></tr><tr><th>Bu Ay</th><th>Kümülatif</th><th>Bu Ay</th><th>Kümülatif</th><th>Bu Ay</th><th>Kümülatif</th><th>Bu Ay</th><th>Kümülatif</th></tr></thead><tbody>${jobs.map(x=>`<tr><td><strong>${esc(x.is_adi)}</strong><small>${esc(x.sozlesme_adi)}</small></td><td>${reportNumber(x.mevcut_hizmet_tutari)}</td><td>${reportNumber(x.kumulatif_hizmet_tutari)}</td><td>${reportNumber(x.mevcut_genel_gider)}</td><td>${reportNumber(x.kumulatif_genel_gider)}</td><td>${reportNumber(x.mevcut_yuklenici_kari)}</td><td>${reportNumber(x.kumulatif_yuklenici_kari)}</td><td class="current-total">${reportNumber(x.mevcut_genel_toplam)}</td><td class="cumulative-total">${reportNumber(x.kumulatif_genel_toplam)}</td></tr>`).join('')}</tbody><tfoot><tr><th>GENEL TOPLAM</th><th>${reportNumber(s.mevcut_hizmet_tutari)}</th><th>${reportNumber(s.kumulatif_hizmet_tutari)}</th><th colspan="4"></th><th>${reportNumber(s.mevcut_genel_toplam)}</th><th>${reportNumber(s.kumulatif_genel_toplam)}</th></tr></tfoot></table></div>`:`<div class="report-empty"><i class="bi bi-bar-chart"></i><strong>${selected} ${esc(d.yil)} için rapor verisi bulunamadı.</strong><span>Bu ay için bordro yüklendiğinde rapor otomatik oluşacaktır.</span></div>`;return`<div class="job-report-heading"><div><span>${esc(d.yil)} · ${selected}</span><h3>İş Bazlı Hakediş Özeti</h3></div><span class="report-scope">${$('#reportJob')?.selectedOptions[0]?.textContent||'Tüm işler'}</span></div><div class="job-report-summary"><article><span>Bu Ay Genel Toplam</span><strong>${reportNumber(s.mevcut_genel_toplam)} ₺</strong><small>${selected} dönemi</small></article><article><span>Kümülatif Genel Toplam</span><strong>${reportNumber(s.kumulatif_genel_toplam)} ₺</strong><small>Ocak–${selected}</small></article><article><span>Bu Ay Hizmet Tutarı</span><strong>${reportNumber(s.mevcut_hizmet_tutari)} ₺</strong><small>Primler dahil</small></article><article><span>Raporlanan İş</span><strong>${esc(s.is_sayisi||0)}</strong><small>Aktif bordro</small></article></div>${table}<div class="report-flow-heading"><div><span>AYLIK GÖRÜNÜM</span><h4>${esc(d.yil)} Hakediş Akışı</h4></div><small>Her kartta ay tutarı ve o aya kadarki kümülatif toplam gösterilir.</small></div><div class="report-flow-grid">${flow.map(x=>`<button type="button" class="report-flow-card ${Number(x.ay)===Number(d.ay)?'active':''} ${x.veri_var?'has-data':''}" data-flow-month="${x.ay}"><span>${months[x.ay]}</span><strong>${compactReportNumber(x.mevcut_toplam)}</strong><small>Kümülatif ${compactReportNumber(x.kumulatif_toplam)}</small></button>`).join('')}</div>`}
  async function loadJobReport(month=selectedReportMonth()){const selected=Number(month);$$('.report-month').forEach(b=>b.classList.toggle('active',Number(b.dataset.month)===selected));const host=$('#reportPreview');if(!host)return;host.innerHTML='<div class="text-center text-secondary py-5">İş bazlı rapor hazırlanıyor…</div>';try{const d=await api('job_progress_report',{query:reportFilters()});(d.months||[]).forEach(x=>{const button=$(`.report-month[data-month="${x.ay}"]`);if(!button)return;button.classList.toggle('has-data',!!x.veri_var);const small=$('small',button);if(small)small.textContent=x.veri_var?compactReportNumber(x.mevcut_toplam):'—'});host.innerHTML=jobReportHtml(d);$$('[data-flow-month]',host).forEach(b=>b.onclick=()=>loadJobReport(b.dataset.flowMonth))}catch(e){host.innerHTML='';notify(e.message,'danger')}}
  function setupJobReports(){const job=$('#reportJob');if(!job)return;const unique=[...new Map((state.options.isler||[]).map(x=>[String(x.id),x])).values()];job.innerHTML='<option value="">Tüm işler</option>'+unique.map(x=>`<option value="${x.id}">${esc(x.ad)}</option>`).join('');$$('.report-month').forEach(b=>b.onclick=()=>loadJobReport(b.dataset.month));job.onchange=()=>loadJobReport();let timer;$('#reportYear').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>loadJobReport(),350)}}
  function progressReportHtml(d){const months=['','OCAK','ŞUBAT','MART','NİSAN','MAYIS','HAZİRAN','TEMMUZ','AĞUSTOS','EYLÜL','EKİM','KASIM','ARALIK'],month=months[Number(d.ay)]||'',total=Number(d.sozlesme_fiyatlariyla_hizmet||0)+Number(d.fiyat_farki||0);return`<div class="classic-progress-report"><table><tbody><tr><th colspan="4" class="report-title">HAKEDİŞ RAPORU</th></tr><tr><th colspan="3" class="report-subtitle">PERSONEL HİZMETİ ALIMI TEMİZLİK İŞLERİ MÜDÜRLÜĞÜ ${month} ${esc(d.yil)}</th><td class="report-no">Hakediş No : ${esc(d.hak_edis_no)}</td></tr><tr><td colspan="4" class="report-date">${reportDate(d.rapor_tarihi)} TARİHİNE KADAR YAPILAN HİZMETİN</td></tr><tr class="gap"><td colspan="4"></td></tr>${reportLine('A','Sözleşme Fiyatları İle Yapılan Hizmet Tutarı',reportNumber(d.sozlesme_fiyatlariyla_hizmet))}${reportLine('B','Fiyat Farkı Tutarı',reportNumber(d.fiyat_farki))}${reportLine('C','Toplam Tutar ( A + B )',reportNumber(total),'strong')}<tr class="gap"><td colspan="4"></td></tr>${reportLine('D','Bir Önceki Hakedişin Toplam Tutarı',reportNumber(d.onceki_hakedis_toplami))}${reportLine('E','Bu Hakedişin Tutarı ( C - D )',reportNumber(d.bu_hakedis_tutari))}${reportLine('F','KDV ( E x %1 )',reportNumber(d.kdv_tutari))}${reportLine('G','Tahakkuk Tutarı',reportNumber(d.tahakkuk_tutari),'strong')}<tr><th rowspan="10" colspan="2" class="deduction-title">KESİNTİLER VE MAHSUPLAR</th><td>a) Sözleşmeye Ait Damga Vergisi ( E x % ... )</td><td>${reportNumber(0)}</td></tr>${deductionLine('b) Ödemeye Ait Damga Vergisi',reportNumber(d.damga_vergisi))}${deductionLine('c) KDV Tevkifatı ( F x ... )',reportNumber(0))}${deductionLine('d) Sosyal Sigortalar Kurumu Kesintisi','-----')}${deductionLine('e) İdare Makinesi Kiraları','-----')}${deductionLine('f) Gecikme Cezası','-----')}${deductionLine('g) Avans Mahsubu','-----')}${deductionLine('h) Bu Hakedişle Ödenen Fiyat Farkı<br>&nbsp;&nbsp;&nbsp;Teminat Kesintisi','-----')}${deductionLine('........................','')}${deductionLine('…………………..','')}${reportLine('H','Kesintiler ve Mahsuplar Toplamı',reportNumber(d.kesinti_toplami),'strong')}${reportLine('','Yükleniciye Ödenecek Tutar ( G - H )',reportNumber(d.odenecek_tutar),'strong')}<tr class="signature-divider"><td colspan="4"></td></tr><tr class="signatures"><td colspan="2">YÜKLENİCİ</td><td colspan="2">D Ü Z E N L E Y E N L E R<br><small>(Yetkili Kontrol Elemanları)</small><div class="approval">....../...../......<br>ONAYLAYAN</div></td></tr></tbody></table></div>`}
  function reportLine(code,label,value,cls=''){return`<tr class="${cls}"><td class="code">${code}</td><td colspan="2">${label}</td><td class="amount">${value}</td></tr>`}
  function deductionLine(label,value){return`<tr><td>${label}</td><td class="amount">${value}</td></tr>`}
  async function previewReport(){const host=$('#classicReportPreview');try{host.innerHTML='<div class="text-center text-secondary py-4">Klasik rapor hazırlanıyor…</div>';const d=await api('simple_progress_report',{query:reportFilters()});host.innerHTML=progressReportHtml(d)}catch(e){host.innerHTML='';notify(e.message,'danger')}}
  const systemState={users:[],roles:[],authorization:null};
