  function systemDate(value){if(!value)return'Henüz giriş yok';const d=new Date(String(value).replace(' ','T'));return Number.isNaN(d.getTime())?esc(value):new Intl.DateTimeFormat('tr-TR',{dateStyle:'short',timeStyle:'short'}).format(d)}
