  function renderSystemMetrics(summary){const items=[['bi-people','Toplam Kullanıcı','toplam_kullanici'],['bi-person-check','Aktif Kullanıcı','aktif_kullanici'],['bi-person-badge','Aktif Rol','aktif_rol'],['bi-shield-check','Tanımlı Yetki','tanimli_yetki'],['bi-activity','Bugünkü İşlem','bugunku_islem']];$('#userMetrics').innerHTML=items.map(x=>`<article><i class="bi ${x[0]}"></i><div><span>${x[1]}</span><strong>${Number(summary[x[2]]||0)}</strong></div></article>`).join('')}
  function renderSystemUsers(rows){$('#userListTitle').textContent=`${rows.length} kullanıcı`;$('#systemUserList').innerHTML=rows.length?rows.map(user=>{const roles=String(user.rol_adlari||'').split(',').map(x=>x.trim()).filter(Boolean);return`<article class="system-user-row"><div class="system-user-identity"><span class="system-user-avatar">${esc(systemInitial(user.ad_soyad))}</span><span><strong>${esc(titleCaseTr(user.ad_soyad))}</strong><small>${esc(user.eposta)}</small></span></div><div class="system-role-chips">${roles.length?roles.map(role=>`<span>${esc(role)}</span>`).join(''):'<small>Rol atanmamış</small>'}</div><div class="system-access-count"><i class="bi bi-key"></i><span><strong>${Number(user.yetki_sayisi||0)} yetki</strong><small>Menü ve işlem erişimi</small></span></div><div class="system-last-login"><strong>${systemDate(user.son_giris_at)}</strong><small>Kayıt: ${systemDate(user.created_at)}</small></div><div class="system-user-actions"><span class="system-user-status ${Number(user.aktif)===1?'active':''}">${Number(user.aktif)===1?'Aktif':'Pasif'}</span><button class="system-icon-button permission system-permissions" type="button" data-id="${user.id}" title="Yetkiler"><i class="bi bi-shield-lock"></i></button><button class="system-icon-button password system-password" type="button" data-id="${user.id}" title="Şifreyi güncelle"><i class="bi bi-key"></i></button><button class="system-icon-button system-edit" type="button" data-id="${user.id}" title="Düzenle"><i class="bi bi-pencil"></i></button><button class="system-icon-button ${Number(user.aktif)===1?'danger':'success'} system-toggle-user" type="button" data-id="${user.id}" data-active="${Number(user.aktif)===1?0:1}" title="${Number(user.aktif)===1?'Pasife al':'Aktifleştir'}"><i class="bi ${Number(user.aktif)===1?'bi-pause-circle':'bi-play-circle'}"></i></button></div></article>`}).join(''):'<div class="system-empty"><i class="bi bi-people"></i><strong>Filtreye uygun kullanıcı bulunamadı</strong></div>';$$('.system-edit').forEach(b=>b.onclick=()=>openSystemUser(systemState.users.find(x=>String(x.id)===b.dataset.id)));$$('.system-password').forEach(b=>b.onclick=()=>openSystemPassword(systemState.users.find(x=>String(x.id)===b.dataset.id)));$$('.system-permissions').forEach(b=>b.onclick=()=>{openSection('yetkilendirme');loadAuthorization(b.dataset.id)});$$('.system-toggle-user').forEach(b=>b.onclick=()=>toggleSystemUser(b.dataset.id,b.dataset.active))}
  function renderSystemRoles(selected=[]){$('#systemRoleOptions').innerHTML=systemState.roles.map(role=>`<label><input type="checkbox" value="${role.id}" ${selected.includes(String(role.id))?'checked':''}><span><i class="bi bi-person-badge"></i><b>${esc(role.ad)}</b><small>${esc(role.aciklama||role.rol_anahtari)}</small></span></label>`).join('')}
  async function loadSystemUsers(){try{const data=await api('user_management',{query:{durum:$('#userStatusFilter').value,ara:$('#userSearchFilter').value}});systemState.users=data.users||[];systemState.roles=data.roles||[];renderSystemMetrics(data.summary||{});renderSystemRoles();renderSystemUsers(systemState.users)}catch(e){notify('Kullanıcı yönetimi yüklenemedi: '+e.message,'danger')}}
  function openSystemUser(user=null){const form=$('#systemUserForm');form.reset();form.elements.id.value=user?.id||'';form.elements.ad_soyad.value=user?.ad_soyad||'';form.elements.eposta.value=user?.eposta||'';form.elements.aktif.checked=user?Number(user.aktif)===1:true;$('#systemUserModal .modal-title').textContent=user?'Kullanıcıyı Düzenle':'Yeni Kullanıcı';$('#userPasswordHelp').textContent=user?'Değişmeyecekse boş bırakın':'Yeni kullanıcı için zorunlu';renderSystemRoles(user?String(user.rol_idleri||'').split(','):[]);systemUserModal.show()}
  function openSystemPassword(user){if(!user)return;const form=$('#systemPasswordForm');form.reset();form.elements.id.value=user.id;$('#passwordUserName').textContent=titleCaseTr(user.ad_soyad);systemPasswordModal.show()}
  async function saveSystemUser(event){event.preventDefault();const form=event.currentTarget,data={id:form.elements.id.value,ad_soyad:form.elements.ad_soyad.value,eposta:form.elements.eposta.value,parola:form.elements.parola.value,aktif:form.elements.aktif.checked?1:0,rol_idleri:$$('#systemRoleOptions input:checked').map(x=>x.value)};try{await api('save_user',{method:'POST',body:{data}});systemUserModal.hide();notify(data.id?'Kullanıcı ve rol atamaları güncellendi.':'Yeni kullanıcı oluşturuldu.');loadSystemUsers()}catch(e){notify(e.message,'danger')}}
  async function toggleSystemUser(id,active){if(!confirm(active==='1'?'Kullanıcı aktifleştirilsin mi?':'Kullanıcı pasife alınsın mı?'))return;try{await api('toggle_user',{method:'POST',body:{id,aktif:active}});notify('Kullanıcı durumu güncellendi.');loadSystemUsers()}catch(e){notify(e.message,'danger')}}
  async function resetSystemPassword(event){event.preventDefault();const form=event.currentTarget;try{await api('reset_user_password',{method:'POST',body:{id:form.elements.id.value,parola:form.elements.parola.value,parola_tekrar:form.elements.parola_tekrar.value}});systemPasswordModal.hide();notify('Kullanıcı şifresi güvenli biçimde güncellendi.');loadSystemLogs()}catch(e){notify(e.message,'danger')}}
  function renderAuthorization(data){systemState.authorization=data;const select=$('#permissionUser'),selected=String(data.selected_user?.id||'');select.innerHTML=(data.users||[]).map(user=>`<option value="${user.id}" ${String(user.id)===selected?'selected':''}>${esc(titleCaseTr(user.ad_soyad))} · ${esc(user.eposta)}</option>`).join('');if(!data.selected_user){$('#selectedPermissionUser').innerHTML='<div class="system-empty"><strong>Yetkilendirilecek kullanıcı bulunamadı</strong></div>';$('#permissionMatrix').innerHTML='';return}const user=data.selected_user;$('#selectedPermissionUser').innerHTML=`<div class="system-selected-user"><span class="system-user-avatar">${esc(systemInitial(user.ad_soyad))}</span><div><span class="system-eyebrow">SEÇİLİ KULLANICI</span><h3>${esc(titleCaseTr(user.ad_soyad))}</h3><p>${esc(user.eposta)}</p></div></div>`;const selectedIds=new Set((data.selected_ids||[]).map(String)),groups=new Map();(data.permissions||[]).forEach(permission=>{const key=`${permission.menu_grubu}|${permission.menu_adi}`;if(!groups.has(key))groups.set(key,{title:permission.menu_adi,group:permission.menu_grubu,items:[]});groups.get(key).items.push(permission)});$('#permissionMatrix').innerHTML=[...groups.values()].map((group,index)=>`<section class="menu-permission-card" data-permission-card><header><div><span class="system-eyebrow">${esc(group.group)}</span><strong>${esc(group.title)}</strong></div><div class="menu-access-buttons"><button type="button" data-level="none">Kapalı</button><button type="button" data-level="view">Görüntüle</button><button type="button" data-level="full">Tam Yetki</button></div></header><div class="menu-permission-body">${group.items.map(item=>`<label class="menu-permission-item"><input type="checkbox" name="yetki_idleri[]" value="${item.id}" data-kind="${item.yetki_turu}" ${selectedIds.has(String(item.id))?'checked':''}><span><strong>${esc(item.ad)}</strong><small>${item.yetki_turu==='goruntule'?'Görüntüleme yetkisi':'Kayıt ve işlem yetkisi'}</small></span></label>`).join('')}</div></section>`).join('');$$('[data-permission-card]').forEach(card=>$$('[data-level]',card).forEach(button=>button.onclick=()=>{const level=button.dataset.level;$$('input[type="checkbox"]',card).forEach(input=>input.checked=level==='full'||(level==='view'&&input.dataset.kind==='goruntule'))}))}
  async function loadAuthorization(userId=''){try{const selected=userId||$('#permissionUser')?.value||'';renderAuthorization(await api('authorization_matrix',{query:{kullanici_id:selected}}))}catch(e){notify('Yetkilendirme ekranı yüklenemedi: '+e.message,'danger')}}
  async function saveAuthorization(event){event.preventDefault();const userId=$('#permissionUser').value;if(!userId)return;try{await api('save_user_permissions',{method:'POST',body:{kullanici_id:userId,yetki_idleri:$$('#permissionMatrix input:checked').map(x=>x.value)}});notify('Kullanıcının menü ve işlem yetkileri güncellendi.');loadAuthorization(userId)}catch(e){notify(e.message,'danger')}}
  async function loadSystemLogs(){try{const data=await api('activity_logs',{query:{kullanici_id:$('#logUserFilter').value,ara:$('#logSearchFilter').value}}),select=$('#logUserFilter'),old=select.value;select.innerHTML='<option value="">Tüm kullanıcılar</option>'+(data.users||[]).map(user=>`<option value="${user.id}">${esc(titleCaseTr(user.ad_soyad))}</option>`).join('');select.value=old;$('#systemLogRows').innerHTML=(data.rows||[]).length?data.rows.map(row=>`<tr><td>${systemDate(row.created_at)}</td><td><strong>${esc(row.kullanici_adi||'Sistem')}</strong><small class="d-block text-secondary">${esc(row.eposta||'')}</small></td><td><span class="badge-status">${esc(String(row.islem||'').replaceAll('_',' '))}</span></td><td>${esc(row.tablo_adi)}${row.kayit_id?` #${row.kayit_id}`:''}</td><td>${esc(row.ip_adresi||'—')}</td></tr>`).join(''):'<tr><td colspan="5" class="text-center text-secondary py-5">İşlem kaydı bulunamadı.</td></tr>'}catch(e){notify('İşlem logları yüklenemedi: '+e.message,'danger')}}
  function setupSystemManagement(){$('#newSystemUser').onclick=()=>openSystemUser();$('#filterUsers').onclick=loadSystemUsers;$('#userSearchFilter').onkeydown=e=>{if(e.key==='Enter')loadSystemUsers()};$('#systemUserForm').onsubmit=saveSystemUser;$('#systemPasswordForm').onsubmit=resetSystemPassword;$('#permissionUser').onchange=e=>loadAuthorization(e.target.value);$('#permissionForm').onsubmit=saveAuthorization;$('#filterLogs').onclick=loadSystemLogs;$('#logSearchFilter').onkeydown=e=>{if(e.key==='Enter')loadSystemLogs()}}
  const hrState={employees:[],reports:null,chartType:'gender'};
